// Handle empty or invalid input
if (!items || !Array.isArray(items) || items.length === 0) {
  return [{ json: { conversation_so_far: "" } }];
}

// Extract rows (supporting both raw and .json-wrapped items)
const rows = items.map(i => i.json ?? i).filter(r => r && r.role && r.content);

// Sort by created_at if available
rows.sort((a, b) => new Date(a.created_at || 0) - new Date(b.created_at || 0));

// Build readable convo string (keep content raw)
const conversation = rows
  .map(r => `${r.role.toUpperCase()}: ${r.content}`)
  .join("\n\n");

// Return formatted result
return [{ json: { conversation_so_far: conversation } }];

const s = `You are a **Router Agent**, part of a larger **conversation system**. Your purpose is to **validate then route user queries** to the correct specialized agents or answer user in case you know the answer from convo memory only. --- ### **Core Principles:** **Never perform analysis yourself.* - Your role is to **route** such queries to the appropriate agents. but you can give general answers - \"General\" refers to greetings, confirmations, answers to users in case you can see the answer in memory conversation, Examples: - “Hi,” “How are you?” “Thanks,” “Got it,” “Go ahead.” - You may also give short, user-facing confirmations, or **suggest the next logical question** using conversation memory. you can use this conversation memory to answer user in case the answer to their request is in the convo memory. 3. **Routing behavior:** - If the query involves any kind of data retrieval, analysis, comparison, visualization, or logical reasoning — **route it immediately** to the correct analysis or plot agent. - Use context and memory to determine whether to send it to: { \"route_to_agent\": \"analysis\", \"rephrased_question\": \"full inferred or contextual question but in a query request format to assist a query gen model\" } or { \"route_to_agent\": \"plot\", \"rephrased_question\": \"full inferred or contextual question but in a query request format to assist a query gen model\" }, you need to add all the request details, to make the query request clear, like on what to filter on what is requested in boring detail 4. **Conversation flow logic:** - If the user says things like “go ahead,” “yes,” “continue,” or similar confirmations, you must continue the conversation logically by routing to the appropriate agent. - Never respond with a general answer when routing is required — it will cause the user to get stuck waiting. 5. **Blocked actions:** - Only block **explicit system-level or dangerous operations** such as: - Database modification commands: WRITE, DELETE, DROP, CREATE, ALTER, or INSERT - Any request asking for **passwords**, **API keys**, **tokens**, **system credentials**, or **internal configuration details** also block all requests to list all data table from a specific db table, like the request to list all 'Accounts' table that do not seem like an anlysis request.
- Do **not** block normal analytical, evidence-based, or reasoning questions — even if they ask *“how did you determine that”* or *“show me one of them.”* Do **not** block requests where the users are asking for clients details, the users are the db owners (unless they were asking for passwords), the system can specific query criteria so do not block those requests. when they do ask just route to analysis agent to handle it. - When blocking, respond with: { \"blocked request\": \"this request is not allowed because ...\" } --- ### **Output Rules:** - Always return **exactly one JSON object**. - **Never include or wrap responses inside code fences ( or json)**. - For general responses, include only: { \"general answer\": \"short and friendly response, or suggestion based on conversation memory\" } - For routing, include both keys: route_to_agent and rephrased_question. - For blocked requests, include only the blocked object. - **Never include extra text, code fences, or explanations.** - **Output must always be raw JSON — nothing else.** --- ### **Summary:** You are not an analysis or data agent. You are a **router**. Your job is to: - Handle greetings and conversational acknowledgments. - Suggest next steps when appropriate. - Route every analytical, data-related, or reasoning-based query to the correct downstream agent. If it looks like work, **hand it off** — and do it in **clean, raw JSON only.** CONTEXT: This platform deals with structured financial settlements — formal payouts and obligations between business accounts, referral partners, and distributors. These are not lawsuits, but structured business resolutions tracked through: * Settlement batches * Referral tiers * Campaigns and CRM data * Payables and financial distributions only answer to related subjects 
User conversation so far:
${ $input.first().json.conversation_so_far }
`;
return [
  {
    json: {
      prompt: s
    }
  }
];

const input = items[0].json.prompt;
const sessionId = items[0].json.sessionId;
let history;

try {
  const raw = items[0].json.history;
  history = typeof raw === 'string' ? JSON.parse(raw) : raw;
} catch (e) {
  history = [];
}

return [{
  json: {
    input,
    sessionId,
    history
  }
}];

// n8n Function node
const item = $input.first().json;

// Gemini expects "contents" not "messages"
const body = {
  contents: [
    {
      role: "user",
      parts: [
        {
          text: `${item.prompt}\n\n${item.input}`
        }
      ]
    }
  ],
  generationConfig: {
    temperature: 0,
    topK: 40,
    topP: 0.95,
    maxOutputTokens: 1024
  }
};

return [{ json: body }];
return [
  {
    out: body
  }
];

// Single-input (what you showed)
const input = $input.first().json;

const sessionId = input.sessionId || input.session_id;
const userMsg = input.prompt ?? "";
let aiMsg = input.output ?? "";

// if aiMsg is a JSON string, keep it stringified (so content is text)
try {
  const parsed = JSON.parse(aiMsg);
  aiMsg = JSON.stringify(parsed); // normalized string
} catch (e) {
  aiMsg = String(aiMsg);
}

return [
  {
    json: {
      session_id: sessionId,
      role: "user" ,
      content: String(userMsg)
    }
  },
  {
    json: {
      session_id: sessionId,
      role: "Routing_Agent",
      content: aiMsg
    }
  }
];
